export default function PartnersCarousel() {
  const partners = [
    { name: "AWS Partner Network", desc: "Advanced Consulting", logo: <AwsLogo /> },
    { name: "Microsoft Solutions", desc: "Gold Partner", logo: <MicrosoftLogo /> },
    { name: "Google Cloud", desc: "Premier Tier", logo: <GoogleCloudLogo /> },
    { name: "Salesforce Consulting", desc: "Ridge Partner", logo: <SalesforceLogo /> },
    { name: "HubSpot Certified", desc: "Platinum Agency", logo: <HubSpotLogo /> },
    { name: "Zoho Premium", desc: "Authorized Partner", logo: <ZohoLogo /> },
    { name: "Odoo Gold", desc: "Official Partner", logo: <OdooLogo /> },
    { name: "Shopify Plus", desc: "Store Developer", logo: <ShopifyLogo /> },
    { name: "SAP Silver", desc: "Enterprise Integrator", logo: <SapLogo /> }
  ];

  return (
    <div className="bg-[#f8fafc] py-12 border-y border-slate-100 overflow-hidden relative w-full">
      <div className="max-w-7xl mx-auto px-6 mb-6 text-center">
        <p className="text-xs font-bold uppercase tracking-[0.25em] text-slate-400">
          Partnered with Startups and Fortune 500 Companies
        </p>
      </div>

      <div className="relative w-full flex overflow-x-hidden">
        {/* Infinite Marquee Wrapper */}
        <div className="flex animate-marquee whitespace-nowrap gap-8 py-2">
          {/* First block of partners */}
          {partners.map((partner, index) => (
            <div
              key={`first-${index}`}
              className="inline-flex items-center gap-4 bg-white px-6 py-4 rounded-xl border border-slate-100 shadow-sm min-w-[260px] hover:border-brand-teal/20 transition-colors"
            >
              <div className="flex items-center justify-center w-12 h-12 rounded-lg bg-slate-50 border border-slate-100 shrink-0">
                {partner.logo}
              </div>
              <div className="flex flex-col justify-center">
                <span className="font-extrabold text-xs text-slate-800 uppercase tracking-wide">
                  {partner.name}
                </span>
                <span className="text-[9px] text-slate-400 font-bold uppercase tracking-wider mt-0.5">
                  {partner.desc}
                </span>
              </div>
            </div>
          ))}
          {/* Second block of partners (duplicate for seamless loop) */}
          {partners.map((partner, index) => (
            <div
              key={`second-${index}`}
              className="inline-flex items-center gap-4 bg-white px-6 py-4 rounded-xl border border-slate-100 shadow-sm min-w-[260px] hover:border-brand-teal/20 transition-colors"
            >
              <div className="flex items-center justify-center w-12 h-12 rounded-lg bg-slate-50 border border-slate-100 shrink-0">
                {partner.logo}
              </div>
              <div className="flex flex-col justify-center">
                <span className="font-extrabold text-xs text-slate-800 uppercase tracking-wide">
                  {partner.name}
                </span>
                <span className="text-[9px] text-slate-400 font-bold uppercase tracking-wider mt-0.5">
                  {partner.desc}
                </span>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
